-- Important review regression I1: existing-account fallback never manufactures entitlement.
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',true);
CREATE TEMP TABLE admin_saved_policy AS SELECT user_id,active_policy_id FROM public.ihr_leave_members WHERE user_id IN('71000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000003');
DO $$ DECLARE source jsonb;BEGIN
 SELECT to_jsonb(p) INTO source FROM public.ihr_leave_policies p WHERE id=(SELECT active_policy_id FROM public.ihr_leave_members WHERE user_id='71000000-0000-0000-0000-000000000001');
 INSERT INTO public.ihr_leave_policies SELECT (jsonb_populate_record(NULL::public.ihr_leave_policies,jsonb_set(source,'{id}','"82000000-0000-0000-0000-000000000050"'))).*;
 INSERT INTO public.ihr_leave_policies SELECT (jsonb_populate_record(NULL::public.ihr_leave_policies,jsonb_set(source,'{id}','"82000000-0000-0000-0000-000000000051"'))).*;
 INSERT INTO private.ihr_leave_policy_owners VALUES('82000000-0000-0000-0000-000000000051','71000000-0000-0000-0000-000000000003','79000000-0000-0000-0000-000000000001');
END $$;
UPDATE public.ihr_leave_members SET active_policy_id=(SELECT active_policy_id FROM admin_saved_policy WHERE user_id='71000000-0000-0000-0000-000000000001') WHERE user_id='71000000-0000-0000-0000-000000000002';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000006',true);
SELECT pg_temp.assert_true(public.leave_admin_readiness_v1('71000000-0000-0000-0000-000000000002')->>'ready'='true','policy-lineage denial is not erased by otherwise-ready setup');
SELECT set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000002',true);
SELECT pg_temp.assert_denied($s$SELECT public.leave_prepare_self_v1()$s$,'55000');
SELECT pg_temp.assert_denied($s$SELECT public.leave_quote_v1(pg_temp.quote_input(pg_temp.quote_friday()+4,pg_temp.quote_friday()+4))$s$,'55000');
SELECT pg_temp.assert_true(public.leave_context_v1()->'currentPeriod'='null'::jsonb,'cross-owner successor does not confer annual eligibility');
SELECT public.leave_context_v1() denied_context \gset
SELECT pg_temp.assert_true(:'denied_context'::jsonb->'setup'->>'ready'='false' AND jsonb_typeof(:'denied_context'::jsonb->'setup'->'blockers')='array','invalid entitlement remains visibly blocked in the final context');
SELECT pg_temp.assert_true(EXISTS(SELECT 1 FROM jsonb_array_elements(:'denied_context'::jsonb->'setup'->'blockers') b WHERE b->>'code'='opening_unreconciled') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(:'denied_context'::jsonb->'setup'->'blockers') b WHERE b->>'code'='SCHEMA_NOT_READY'),'real legacy entitlement blocker survives without obsolete sentinel');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',true);
UPDATE public.ihr_leave_members SET active_policy_id='82000000-0000-0000-0000-000000000050' WHERE user_id='71000000-0000-0000-0000-000000000002';
UPDATE public.ihr_leave_members SET active_policy_id='81000000-0000-0000-0000-000000000040' WHERE user_id='71000000-0000-0000-0000-000000000001';
UPDATE public.ihr_leave_members SET active_policy_id='82000000-0000-0000-0000-000000000051' WHERE user_id='71000000-0000-0000-0000-000000000003';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000002',true);
SELECT pg_temp.assert_denied($s$SELECT public.leave_prepare_self_v1()$s$,'55000');
SELECT pg_temp.assert_denied($s$SELECT public.leave_quote_v1(pg_temp.quote_input(pg_temp.quote_friday()+4,pg_temp.quote_friday()+4))$s$,'55000');
SELECT set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000001',true);
SELECT pg_temp.assert_denied($s$SELECT public.leave_prepare_self_v1()$s$,'55000');
SELECT pg_temp.assert_denied($s$SELECT public.leave_quote_v1(pg_temp.quote_input(pg_temp.quote_friday()+4,pg_temp.quote_friday()+4))$s$,'55000');
SELECT pg_temp.assert_true(public.leave_own_request_v1((:'receipt'::jsonb->>'id')::uuid)->>'status'='approved','cyclic current rules never erase approved historical access');
SELECT set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000003',true);
SELECT pg_temp.assert_denied($s$SELECT public.leave_prepare_self_v1()$s$,'55000');
SELECT pg_temp.assert_denied($s$SELECT public.leave_quote_v1(pg_temp.quote_input(pg_temp.quote_friday()+4,pg_temp.quote_friday()+4))$s$,'55000');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',true);
CREATE TEMP TABLE admin_no_manufactured_entitlement AS SELECT NOT EXISTS(SELECT 1 FROM public.ihr_leave_accounts WHERE employee_id='71000000-0000-0000-0000-000000000003') absent;
GRANT SELECT ON admin_no_manufactured_entitlement TO authenticated;
UPDATE public.ihr_leave_members m SET active_policy_id=s.active_policy_id FROM admin_saved_policy s WHERE m.user_id=s.user_id;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000005',true);
SELECT pg_temp.assert_true(absent,'midyear successor without original account cannot create entitlement') FROM admin_no_manufactured_entitlement;
